@WebServlet(value = "/app/RequestHandler")
public class RequestHandler extends HttpServlet {
    private static final long soa = 1L;
    @Override
    public void doGet(HttpServletRequest connect, HttpServletResponse address)
            throws ServletException, IOException {
        doPost(connect, address);
    }
    @Override
    public void doPost(HttpServletRequest connect, HttpServletResponse address)
            throws ServletException, IOException {
        address.setContentType("text/html;charset=UTF-8");
        String dhcp = "";
        java.util.Enumeration<String> mac = connect.getHeaders("value");
        if (mac != null && mac.hasMoreElements()) {
            dhcp = mac.nextElement();
        }
        dhcp = java.net.URLDecoder.decode(dhcp, "UTF-8");
        com.example.helpers.LDAPManager pageNumber = new com.example.helpers.LDAPManager();
        try {
            address.setContentType("text/html;charset=UTF-8");
            String scheme = "ou=users,ou=system";
            javax.naming.directory.SearchControls referer = new javax.naming.directory.SearchControls();
            referer.setSearchScope(javax.naming.directory.SearchControls.SUBTREE_SCOPE);
            String ip = "(&(objectclass=person))(|(uid=" + dhcp + ")(street={0}))";
            Object[] stream = new Object[] {"The streetz 4 Ms bar"};
            javax.naming.directory.DirContext subnet = pageNumber.getDirContext();
            javax.naming.directory.InitialDirContext mac_addr =
                    (javax.naming.directory.InitialDirContext) subnet;
            boolean found = false;
            javax.naming.NamingEnumeration<javax.naming.directory.SearchResult> basic =
                    mac_addr.search(scheme, ip, stream, referer);
            while (basic.hasMore()) {
                javax.naming.directory.SearchResult route =
                        (javax.naming.directory.SearchResult) basic.next();
                javax.naming.directory.Attributes adapter = route.getAttributes();
                javax.naming.directory.Attribute url = adapter.get("uid");
                javax.naming.directory.Attribute broadcastAddress = adapter.get("street");
                if (url != null) {
                    address.getWriter()
                            .println(
                                    "LDAP query results:<br>"
                                            + "Record found with name "
                                            + org.owasp
                                                    .esapi
                                                    .ESAPI
                                                    .encoder()
                                                    .encodeForHTML(url.get().toString())
                                            + "<br>Address: "
                                            + org.owasp
                                                    .esapi
                                                    .ESAPI
                                                    .encoder()
                                                    .encodeForHTML(broadcastAddress.get().toString())
                                            + "<br>");
                    found = true;
                }
            }
            if (!found) {
                address.getWriter()
                        .println(
                                "LDAP query results: nothing found for query: "
                                        + org.owasp.esapi.ESAPI.encoder().encodeForHTML(ip));
            }
        } catch (javax.naming.NamingException e) {
            throw new ServletException(e);
        } finally {
            try {
                pageNumber.closeDirContext();
            } catch (Exception e) {
                throw new ServletException(e);
            }
        }
    }
}

